 "content": "from collections import Counter, deque

def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen, out = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q, pts = deque([(r, c)]), set()
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                pts.add((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            out.append((color, pts))
    return out

def _l(pts):
    r0, r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0, c1 = min(c for r,c in pts), max(c for r,c in pts)
    if len(pts) < 5:
        return None
    for r in (r0, r1):
        for c in (c0, c1):
            if pts == ({(r,x) for x in range(c0,c1+1)} | {(y,c) for y in range(r0,r1+1)}):
                return r, c, (1 if r == r0 else -1), (1 if c == c0 else -1)
    return None

def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)
    markers = [(len(pts), color, pts, _l(pts)) for color, pts in comps if _l(pts)]
    if not markers:
        return [row[:] for row in grid]
    _, color, _, (r, c, vd, hd) = max(markers, key=lambda x: x[0])
    # The L's two arms indicate a diagonal sector; recolor its dominant object.
    candidates = []
    for obj_color, pts in comps:
        if obj_color == color or _l(pts):
            continue
        cy = sum(y for y,x in pts) / len(pts)
        cx = sum(x for y,x in pts) / len(pts)
        if (cy-r)*vd >= 0 or (cx-c)*hd >= 0:
            continue
        candidates.append((len(pts), pts))
    if not candidates:
        return [row[:] for row in grid]
    target = max(candidates, key=lambda x: x[0])[1]
    out = [row[:] for row in grid]
    for y, x in target:
        out[y][x] = color
    return out
